let admissionsEvidence=null,admissionsLoad=null;
function admissionSettings(){let s={};try{s=JSON.parse(localStorage.getItem('camino-admission-settings')||'{}')}catch{}return{institution:AdmissionsEstimator.college(state.profile?.target||'UW Seattle'),route:/Transfer|Community|Running Start/.test(state.profile?.grade||'')?'transfer':/University/.test(state.profile?.grade||'')?'current-student':'first-year',residency:'unknown',origin:'unknown',major:state.profile?.major||'',programId:state.profile?.primaryProgramId||'',factor:1,...s}}
function enteredAdmissionCohorts(){try{const r=JSON.parse(localStorage.getItem('camino-admission-cohorts')||'[]');return Array.isArray(r)?r.slice(-12):[]}catch{return[]}}
function admissionsEstimatorPanel(){const s=admissionSettings();return `<section class="admissions-estimator" id="admissions-estimates"><span class="eyebrow">EVIDENCE, NOT A GUARANTEE</span><h2>Admission estimates & scenarios</h2><p>Select the applicant group that actually fits you. Published cohort rates provide a starting point; they do not establish your individual probability. GPA and writing feedback are reviewed separately because no calibrated public GPA/essay adjustment model is loaded.</p><form id="admission-estimate-form" class="form-grid"><label>College<select name="institution">${ProgramCatalog.institutions.map(p=>`<option ${p.name===s.institution?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label><label>Applicant route<select name="route">${[['first-year','First-year entry'],['transfer','Transfer entry'],['current-student','Current-student major application']].map(([v,t])=>`<option value="${v}" ${s.route===v?'selected':''}>${t}</option>`).join('')}</select></label><label>Residency<select name="residency">${[['unknown','Not specified'],['wa','Washington resident'],['nonwa','Non-Washington resident']].map(([v,t])=>`<option value="${v}" ${s.residency===v?'selected':''}>${t}</option>`).join('')}</select></label><label>Transfer origin<select name="origin">${[['unknown','Not specified / not transferring'],['wacc','Washington community college'],['other','Other two-year / four-year institution']].map(([v,t])=>`<option value="${v}" ${s.origin===v?'selected':''}>${t}</option>`).join('')}</select></label><div class="admission-major"><label>Exact major / credential</label>${catalogDirectionControl('admission-major',s.major,s.programId)}</div><label>What-if odds factor<select name="factor">${[[1,'1× — cohort starting point'],[.5,'0.5× odds — illustrative only'],[2,'2× odds — illustrative only']].map(([v,t])=>`<option value="${v}" ${Number(s.factor)===v?'selected':''}>${t}</option>`).join('')}</select></label><button class="btn primary">Calculate sourced estimate</button></form><div id="admission-estimate-result" aria-live="polite">Loading the public evidence register…</div><details><summary>Add a published cohort for another major</summary><p>Use actual applicants and admits for the selected college, major, route, residency and transfer-origin settings. Entered figures are labelled unverified until independently checked. Do not use enrolled-student counts as admits.</p><form id="admission-cohort-form" class="form-grid"><label>Applicants<input type="number" name="applicants" min="1" max="10000000" required></label><label>Admitted<input type="number" name="admitted" min="0" max="10000000" required></label><label>Population and scope<input name="population" required maxlength="300" placeholder="Eligible current UW students applying to this major"></label><label>Cohort / application cycle<input name="cohort" required maxlength="150"></label><label>Public source URL<input type="url" name="source" required></label><button class="btn">Save this cohort for the selected major</button></form></details><details><summary>Method, uncertainty and limitations</summary><p>For counts, the starting point is (admits + 0.5) / (applicants + 1), a Jeffreys-smoothed cohort estimate. The displayed interval is a 95% Wilson interval for the observed cohort rate under a binomial model. It is not a 95% interval for your personal chance or a forecast of next year's selection.</p><p>Where only a rounded rate is published, no sample-size interval is invented. The 0.5×–2× odds scenario band is illustrative sensitivity, not a confidence interval. Odds conversion: p × factor / (1 − p + p × factor). These factors are assumptions, not measured GPA, essay or activity effects.</p><p>Campus, direct-to-college and major admission are different events. Their rates are never multiplied as though independent. Historical zero admits does not prove zero future chance. Missing routes remain explicitly unmatched rather than receiving a fabricated percentage.</p></details></section>`}
function admissionEstimateCard(label,result,factor){const r=AdmissionsEstimator.scenario(result,factor);if(!r)return `<article class="degree-goal"><h3>${label}</h3><strong>No matching published cohort in this register</strong><p>Check the route and source; a different event's rate is not a substitute.</p></article>`;const m=r.record;return `<article class="degree-goal admission-rate-card"><h3>${label}</h3><div class="admission-number">${AdmissionsEstimator.format(r.scenario)}</div><p>${factor===1?'Cohort-based starting-point estimate':'Illustrative odds scenario — not a personal prediction'}</p><p><strong>${esc(m.program)}</strong> · ${esc(m.population)} · ${esc(m.cohort)}</p>${r.applicants?`<p>${r.admitted.toLocaleString()} admitted / ${r.applicants.toLocaleString()} applicants · observed ${(r.observed*100).toFixed(1)}%</p><p>Observed-cohort 95% interval: ${(r.interval[0]*100).toFixed(1)}–${(r.interval[1]*100).toFixed(1)}%. This is not your individual interval.</p>`:'<p>Published rounded rate; denominator not supplied. No statistical interval calculated.</p>'}<p>Illustrative 0.5×–2× odds band: ${AdmissionsEstimator.format(r.sensitivity[0])}–${AdmissionsEstimator.format(r.sensitivity[1])}.</p><p class="quiet-note">${esc(r.method)}${m.entered?' · Entered by you; not independently verified.':''}</p><a class="journey-secondary" href="${esc(ProductCore.safeURL(m.sourceUrl))}" target="_blank" rel="noopener">Published source ↗</a></article>`}
function paintAdmissions(){if(typeof document==='undefined')return;const target=document.querySelector('#admission-estimate-result');if(!target||!admissionsEvidence)return;const s=admissionSettings(),selected=AdmissionsEstimator.select(s,admissionsEvidence.metrics,enteredAdmissionCohorts());const gpas=admissionsEvidence.metrics.filter(m=>m.institution===s.institution&&m.route===(s.route==='first-year'?'First-year':'Transfer')&&/^(?:mean-|middle-50)/.test(m.metric));target.innerHTML=`<div class="degree-goals">${admissionEstimateCard('College entry',selected.campus,Number(s.factor)||1)}${admissionEstimateCard('Major / direct-entry route',selected.major,Number(s.factor)||1)}</div>${gpas.length?`<details><summary>Published GPA context—not a probability adjustment</summary>${gpas.map(m=>`<article><h4>${esc(m.metric.replaceAll('-',' '))}: ${typeof m.value==='number'?m.value.toFixed(2):esc(m.value.p25+'–'+m.value.p75)}</h4><p>${esc(m.population)} · ${esc(m.cohort)}</p><p>${esc(m.warning||'Check the exact GPA definition and applicant group.')}</p><a href="${esc(ProductCore.safeURL(m.sourceUrl))}" target="_blank" rel="noopener">Public GPA source ↗</a></article>`).join('')}</details>`:''}${selected.notes.map(n=>`<p class="quiet-note">${esc(n)}</p>`).join('')}<p>Evidence register checked ${esc(admissionsEvidence.checked)}. The available public data does not support an independently validated personal admission percentage.</p>`}
function bindAdmissionsEstimator(){const form=document.querySelector('#admission-estimate-form');if(!form)return;const read=()=>{const f=Object.fromEntries(new FormData(form)),p=String(f.major).startsWith('catalog:')?ProgramCatalog.programs.find(p=>p.id===f.major.slice(8)):null;return{institution:p?.institution||f.institution,route:f.route,residency:f.residency,origin:f.origin,major:p?.title||f.major,programId:p?.id||'',factor:Number(f.factor)||1}};form.onsubmit=e=>{e.preventDefault();localStorage.setItem('camino-admission-settings',JSON.stringify(read()));paintAdmissions()};form.querySelector('[data-catalog-direction]').addEventListener('change',()=>{const value=read();if([...form.elements.institution.options].some(o=>o.value===value.institution))form.elements.institution.value=value.institution});document.querySelector('#admission-cohort-form').onsubmit=e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target)),s=read(),n=Number(f.applicants),k=Number(f.admitted),source=ProductCore.safeURL(f.source);if(!s.major||!source||!Number.isInteger(n)||!Number.isInteger(k)||n<1||k<0||k>n)return toast('Choose a major and enter valid applicants, admits and a public source URL.');const records=enteredAdmissionCohorts();records.push({id:'entered-'+Date.now(),entered:true,institution:s.institution,program:s.major,programId:s.programId,route:s.route,residency:s.residency,origin:s.origin,population:f.population,cohort:f.cohort,sourceUrl:source,value:{applicants:n,admitted:k}});localStorage.setItem('camino-admission-settings',JSON.stringify(s));localStorage.setItem('camino-admission-cohorts',JSON.stringify(records.slice(-12)));paintAdmissions();toast('Cohort saved locally and labelled as entered by you.')};if(admissionsEvidence)paintAdmissions();else{admissionsLoad||=fetch('admissions-evidence.json').then(r=>{if(!r.ok)throw Error('Evidence register unavailable');return r.json()}).then(d=>{if(!Array.isArray(d.metrics))throw Error('Evidence register unavailable');return admissionsEvidence=d}).catch(e=>{admissionsLoad=null;const t=typeof document==='undefined'?null:document.querySelector('#admission-estimate-result');if(t)t.textContent=e.message;});admissionsLoad.then(paintAdmissions)}}
